import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.Mockito.when;
import org.junit.Test;
import com.ezylang.evalex.parser.ParseException;
import com.ezylang.evalex.parser.Token;
import com.ezylang.evalex.parser.Tokenizer;
import com.ezylang.evalex.config.ExpressionConfiguration;
import com.ezylang.evalex.operators.OperatorIfc;
import com.ezylang.evalex.config.FunctionDictionaryIfc;
import com.ezylang.evalex.config.OperatorDictionaryIfc;
import com.ezylang.evalex.functions.FunctionIfc;
import org.mockito.Mockito;

import java.util.List;

public class TokenizerTests {

    @Test
    public void parseEmptyStringTest() {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("", configuration);
        try {
            List<Token> tokens = tokenizer.parse();
            assertTrue(tokens.isEmpty());
        } catch (ParseException e) {
            fail("ParseException should not have been thrown for an empty string");
        }
    }

    @Test(expected = ParseException.class)
    public void parseWithInvalidCharacterTest() throws ParseException {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("A", configuration);
        tokenizer.parse();
    }

    @Test
    public void parseWithValidOperatorTest() {
        OperatorIfc operator = Mockito.mock(OperatorIfc.class);
        OperatorDictionaryIfc dictionary = Mockito.mock(OperatorDictionaryIfc.class);
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        when(dictionary.getOperator("+")).thenReturn(operator);
        when(configuration.getOperatorDictionary()).thenReturn(dictionary);
        Tokenizer tokenizer = new Tokenizer("+", configuration);
        try {
            List<Token> tokens = tokenizer.parse();
            assertTrue(tokens.size() == 1 && tokens.get(0).getType() == Token.TokenType.OPERATOR);
        } catch (ParseException e) {
            fail("ParseException should not have been thrown for a valid operator");
        }
    }

    @Test
    public void parseWithValidFunctionTest() {
        FunctionIfc function = Mockito.mock(FunctionIfc.class);
        FunctionDictionaryIfc dictionary = Mockito.mock(FunctionDictionaryIfc.class);
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        when(dictionary.getFunction("SUM")).thenReturn(function);
        when(configuration.getFunctionDictionary()).thenReturn(dictionary);
        Tokenizer tokenizer = new Tokenizer("SUM", configuration);
        try {
            List<Token> tokens = tokenizer.parse();
            assertTrue(tokens.size() == 1 && tokens.get(0).getType() == Token.TokenType.FUNCTION);
        } catch (ParseException e) {
            fail("ParseException should not have been thrown for a valid function");
        }
    }

    @Test
    public void parseStringLiteralTest() {
        ExpressionConfiguration configuration = Mockito.mock(ExpressionConfiguration.class);
        Tokenizer tokenizer = new Tokenizer("\"value\"", configuration);
        try {
            Token token = tokenizer.parseStringLiteral();
            assertTrue(token.getType() == Token.TokenType.LITERAL_DECIMAL);
        } catch (ParseException e) {
            fail("ParseException should not have been thrown for a valid string literal");
        }
    }

